  /* ---------- engagement bait ---------- */

  /* Rule rows are identical for bait and account signals: a toggle, a label
     and hint, an optional threshold, and a weight. One implementation, so a fix
     to either lands in both. */
  function renderRuleList({ rules, configFor, container, settingsKey, onChange }) {
    const box = $(container);
    box.textContent = "";

    for (const rule of rules) {
      const cfg = configFor(rule.id, settings);

      const row = document.createElement("div");
      row.className = "bait-rule" + (cfg.on ? "" : " off");

      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.checked = cfg.on;
      cb.id = settingsKey + "-rule-" + rule.id;
      cb.addEventListener("change", () => {
        overrideRule(settingsKey, configFor, rule.id, { on: cb.checked });
        onChange();
      });

      const label = document.createElement("label");
      label.htmlFor = cb.id;
      label.append(rule.label);
      if (rule.hint) {
        const hint = document.createElement("small");
        hint.className = "hint";
        hint.textContent = rule.hint;
        label.appendChild(hint);
      }

      /* A rule may declare one param or several - "nearly equal" needs both a
         floor and a tolerance, and one of them alone left the other hidden. */
      const params = rule.params || (rule.param ? [rule.param] : []);
      for (const param of params) {
        const wrap = document.createElement("span");
        wrap.className = "weight";
        const picker = document.createElement("select");
        /* An explicit list where a range would be absurd - 500 to 20,000 is
           not a dropdown anyone wants to scroll. */
        const choices = param.values
          ? param.values
          : (() => {
              const out = [];
              const wide = param.max - param.min > 40;
              for (let i = param.min; i <= param.max; i++) {
                if (wide && i % 5 !== 0 && i !== param.min) continue;
                out.push(i);
              }
              return out;
            })();
        for (const value of choices) {
          const text = param.suffix ? value + param.suffix : String(value);
          picker.add(new Option(text, String(value), false, value === cfg[param.key]));
        }
        picker.disabled = !cfg.on;
        picker.addEventListener("change", () =>
          overrideRule(settingsKey, configFor, rule.id, { [param.key]: Number(picker.value) })
        );
        wrap.append(picker, " " + param.label);
        label.appendChild(wrap);
      }

      const weightWrap = document.createElement("span");
      weightWrap.className = "weight";
      weightWrap.append("worth ");
      const weight = document.createElement("select");
      for (let i = 1; i <= 5; i++) {
        weight.add(new Option(String(i), String(i), false, i === cfg.weight));
      }
      weight.disabled = !cfg.on;
      weight.addEventListener("change", () =>
        overrideRule(settingsKey, configFor, rule.id, { weight: Number(weight.value) })
      );
      weightWrap.appendChild(weight);

      row.append(cb, label, weightWrap);
      box.appendChild(row);
    }
  }

  function overrideRule(settingsKey, configFor, id, patch) {
    const current = configFor(id, settings);
    settings[settingsKey].rules = {
      ...settings[settingsKey].rules,
      [id]: { ...current, ...patch }
    };
    save();
  }

  function renderBait() {
    $("baitEnabled").checked = settings.bait.enabled;
    $("baitShowScores").checked = settings.bait.showScores;
    $("baitHighlight").checked = settings.bait.highlight;
    $("baitHighlightOnlyScored").checked = settings.bait.highlightOnlyScored;
    $("baitHighlightOnlyScored").disabled = !settings.bait.highlight;
    $("baitHide").checked = settings.bait.hide;

    renderModeOverride("baitModeOverride", "bait");

    const sel = $("baitThreshold");
    sel.textContent = "";
    for (let i = 1; i <= 10; i++) {
      sel.add(new Option(String(i), String(i), false, i === settings.bait.threshold));
    }

    renderRuleList({
      rules: MEDX.bait.RULES,
      configFor: MEDX.bait.configFor,
      container: "bait-rules",
      settingsKey: "bait",
      onChange: renderBait
    });
  }

