    /* Always re-encoded, never passed through. The first version kept the
       original when it was under three megabytes, which meant a large file was
       stored as-is and then handed to every tab as one enormous data URL —
       slow at best, and silently nothing at worst.

       1920px is plenty for a backdrop, and the quality steps down until the
       result fits the budget rather than hoping one guess lands. */
    const MAX_EDGE = 1920;
    const MAX_BYTES = 1_500_000;

    function loadImage(file) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onerror = () => reject(new Error("could not read that file"));
        reader.onload = () => {
          const img = new Image();
          img.onerror = () => reject(new Error("that file isn't an image"));
          img.onload = () => resolve(img);
          img.src = reader.result;
        };
        reader.readAsDataURL(file);
      });
    }

    async function shrink(file) {
      const img = await loadImage(file);
      if (!img.width || !img.height) throw new Error("that image has no size");

      const scale = Math.min(1, MAX_EDGE / Math.max(img.width, img.height));
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.round(img.width * scale));
      canvas.height = Math.max(1, Math.round(img.height * scale));

      const ctx = canvas.getContext("2d");
      if (!ctx) throw new Error("could not prepare the image");
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

      /* JPEG has no transparency, so an image that uses it is kept as a PNG —
         otherwise the clear parts come back as black and a cut-out over a
         chosen background colour is impossible.

         Sampled rather than scanned pixel by pixel: a full read of a 1920px
         canvas is eight megabytes of array for a yes-or-no answer. */
      function hasAlpha() {
        const step = 4 * 7; // every seventh pixel
        try {
          const { data: px } = ctx.getImageData(0, 0, canvas.width, canvas.height);
          for (let i = 3; i < px.length; i += step) {
            if (px[i] < 250) return true;
          }
        } catch {
          return false; // a tainted canvas cannot be read; assume none
        }
        return false;
      }

      const transparent = hasAlpha();
      let data = "";

      if (transparent) {
        /* PNG has no quality dial, so the size comes down by shrinking. */
        let scaled = canvas;
        for (let attempt = 0; attempt < 4; attempt++) {
          data = scaled.toDataURL("image/png");
          if (data.length <= MAX_BYTES) break;
          const smaller = document.createElement("canvas");
          smaller.width = Math.max(1, Math.round(scaled.width * 0.7));
          smaller.height = Math.max(1, Math.round(scaled.height * 0.7));
          smaller.getContext("2d").drawImage(scaled, 0, 0, smaller.width, smaller.height);
          scaled = smaller;
        }
        if (data.length > MAX_BYTES) {
          throw new Error("that transparent image is too large — try a smaller one");
        }
        return {
          data,
          width: scaled.width,
          height: scaled.height,
          kind: "png"
        };
      }

      for (const quality of [0.85, 0.7, 0.55, 0.4]) {
        data = canvas.toDataURL("image/jpeg", quality);
        if (data.length <= MAX_BYTES) break;
      }
      if (data.length > MAX_BYTES) {
        throw new Error("that image is too detailed to store — try a smaller one");
      }
      return { data, width: canvas.width, height: canvas.height, kind: "jpeg" };
    }

    /* Animated backgrounds. Redrawing onto a canvas — which is how stills are
       shrunk — keeps only the first frame, so anything that moves is stored as
       it arrived, within a size cap, and never touches the canvas.

       The cap is on the file rather than the data URL: base64 adds a third,
       and local storage holds about ten megabytes in all. */
    const MAX_MOTION_BYTES = 5 * 1024 * 1024;

    function readAsDataURL(file) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onerror = () => reject(new Error("could not read that file"));
        reader.onload = () => resolve(reader.result);
        reader.readAsDataURL(file);
      });
    }

    /* As much of the file as could be stored anyway: a GIF's second frame
       sits after the whole of its first, which for a large one is well past
       the first 256KB that used to be read — so big animated GIFs were taken
       for stills and flattened to one frame. */
    async function isAnimated(file) {
      const head = new Uint8Array(await file.slice(0, MAX_MOTION_BYTES).arrayBuffer());
      return MEDX.isAnimatedImage(head, file.type);
    }

    async function prepareBackground(file) {
      const isVideo = /^video\/(mp4|webm)$/.test(file.type);
      const moving = isVideo || (await isAnimated(file));

      if (!moving) return shrink(file);

      if (file.size > MAX_MOTION_BYTES) {
        throw new Error(
          `that ${isVideo ? "video" : "animation"} is ${(file.size / 1048576).toFixed(1)}MB — the limit is 5MB`
        );
      }
      const data = await readAsDataURL(file);
      return {
        data,
        width: "",
        height: "",
        kind: isVideo ? "video" : "animated " + file.type.replace("image/", "")
      };
    }

    $("backgroundImageFile").addEventListener("change", async (e) => {
      const file = e.target.files && e.target.files[0];
      if (!file) return;
      const status = $("backgroundImageStatus");
      status.textContent = "reading…";
      try {
        const { data, width, height, kind } = await prepareBackground(file);
        await chrome.storage.local.set({ medxBackgroundImage: data });

        /* Storage can accept the write and still be over quota, so it is read
           back rather than assumed. */
        const check = await chrome.storage.local.get("medxBackgroundImage");
        if (!check.medxBackgroundImage) {
          throw new Error("the image could not be stored");
        }

        settings.backgroundImage = true;
        save();
        renderAll();
        status.textContent = `${width ? width + "x" + height + " " : ""}${kind}, ${Math.round(
          data.length / 1024
        )}kB`;
      } catch (err) {
        status.textContent = String((err && err.message) || err);
        console.error("[MED-X] background image:", err);
      }
      e.target.value = "";
    });

