      if (!profile) return null;

      if (cfg.automated && profile.automated) return "Automated";

      const label = profile.label;
      if (!label) return null;
      const text = label.toLowerCase();
      if (cfg.parody && text.includes("parody")) return label;
      if (cfg.commentary && text.includes("commentary")) return label;
      if (cfg.fan && text.includes("fan")) return label;
