    cache: new Map(),   // status id -> { type, ms, tall }
    replies: new Map(),   // status id -> { to, conv }
    links: new Map(),     // status id -> [host, ...] it links out to
    convRoots: new Map(), // conversation id -> handle who started it
    langs: new Map(), // status id -> the language X recorded for it
    sources: new Map(), // status id -> { name, host, official }
    authorAnswered: new Set(), // post ids the thread's author replied to
    quotes: new Map(),       // status id -> the status id it quotes
    quoteAuthors: new Map(), // quoted status id -> the handle that wrote it
