  const MEDX = (window.MEDX = window.MEDX || {});

  const DAY = 86400000;

  function ageDays(profile) {
    if (!profile || !profile.created) return null;
    return Math.max(0, (Date.now() - profile.created) / DAY);
  }

  /* A gold or grey badge — a verified organisation or government account. */
  function isOrganisation(handle) {
    const found = MEDX.verified && MEDX.verified.get(handle);
    return !!found && (found.type === "Business" || found.type === "Government");
  }

  /* Lifetime average: total posts over the account's whole life. Fine for an
     account that has behaved consistently, misleading for one that was quiet
     for a decade and started posting hourly last week. */
  function lifetimeRate(profile) {
    const age = ageDays(profile);
    if (age === null || profile.tweets === null || profile.tweets === undefined) return null;
    return profile.tweets / Math.max(1, age);
  }

