    return String(text || "")
      .replace(/https?:\/\/\S+/gi, " ")
      .replace(/\b[\w.-]+\.(com|net|org|io|co|me|tv|gg|app|store|shop|link|ee|ai)(\/\S*)?/gi, " ")
      .replace(/@\w+/g, " ")
